/* eslint-disable import/no-cycle */

import { get } from 'lodash';
import OpenApiV2 from './open-api-v2.ts';
import MarkupTypes from './MarkupTypes.ts';
import { parseODataMetadata, generateSwaggerPaths, generateSwaggerDefinitions, type ODataMetadata } from './odata-metadata-parser.ts';

/**
 * ODataApi extends OpenApiV2 to inherit all OpenAPI methods
 * since OData APIs include swagger: "2.0" for compatibility.
 * We override only the OData-specific methods.
 */
const DEFAULT_ODATA_VERSION = '4.0';

export default class ODataApi extends OpenApiV2 {
  private parsedMetadata: ODataMetadata | null = null;

  private metadataFetchPromise: Promise<void> | null = null;

  constructor(api: any) {
    super(api);
    // Auto-generate paths and definitions from metadata if they're empty
    this.initializeFromMetadata();
  }

  /**
   * Initialize paths and definitions from parsed metadata if they're empty
   * If metadata XML is not embedded, fetch it from the service
   */
  private initializeFromMetadata(): void {
    const metadataXml = this.api['x-odata-metadata-xml'];
    
    if (metadataXml) {
      // Metadata is embedded, parse it immediately
      try {
        const metadata = parseODataMetadata(metadataXml);
        this.parsedMetadata = metadata;
        this.generatePathsAndDefinitions(metadata);
      } catch (error) {
        console.error('[ODataApi] Failed to initialize from embedded metadata:', error);
      }
    } else {
      // Metadata not embedded, fetch it from the service
      this.fetchAndParseMetadata();
    }
  }

  /**
   * Fetch metadata from the OData service and parse it
   */
  private async fetchAndParseMetadata(): Promise<void> {
    // Prevent multiple simultaneous fetches
    if (this.metadataFetchPromise) {
      return this.metadataFetchPromise;
    }

    this.metadataFetchPromise = (async () => {
      try {
        const metadataUrl = this.getMetadataUrl();
        
        if (!metadataUrl) {
          console.error('[ODataApi] Cannot fetch metadata: no metadata URL available');
          return;
        }

        const response = await fetch(metadataUrl, {
          method: 'GET',
          headers: {
            'Accept': 'application/xml'
          }
        });
        
        if (!response.ok) {
          throw new Error(`Failed to fetch metadata: ${response.status} ${response.statusText}`);
        }

        const metadataXml = await response.text();
        
        // Store the fetched metadata in the API object for future use
        this.api['x-odata-metadata-xml'] = metadataXml;

        // Parse and generate paths/definitions
        const metadata = parseODataMetadata(metadataXml);
        this.parsedMetadata = metadata;
        
        this.generatePathsAndDefinitions(metadata);

        // Dispatch custom event to notify components that metadata has loaded
        window.dispatchEvent(new CustomEvent('odata-metadata-loaded', {
          detail: {
            api: this.api,
            entitySets: metadata.entitySets,
            operations: [...metadata.functions, ...metadata.actions]
          }
        }));

      } catch (error) {
        console.error('[ODataApi] Failed to fetch and parse OData metadata:', error);
        if (error instanceof Error) {
          console.error('[ODataApi] Error details:', error.message);
          console.error('[ODataApi] Error stack:', error.stack);
        }
        throw error;
      }
    })();

    return this.metadataFetchPromise;
  }

  /**
   * Generate Swagger paths and definitions from parsed metadata
   */
  private generatePathsAndDefinitions(metadata: ODataMetadata): void {
    // Generate paths if empty or missing
    if (!this.api.paths || Object.keys(this.api.paths).length === 0) {
      this.api.paths = generateSwaggerPaths(metadata);
    }

    // Generate definitions if empty or missing
    if (!this.api.definitions || Object.keys(this.api.definitions).length === 0) {
      this.api.definitions = generateSwaggerDefinitions(metadata);
    }
  }

  /**
   * Ensure metadata is loaded before accessing it
   */
  private async ensureMetadataLoaded(): Promise<void> {
    if (this.parsedMetadata) {
      return;
    }

    if (this.metadataFetchPromise) {
      await this.metadataFetchPromise;
    }
  }

  /**
   * Get parsed metadata (lazy load and cache)
   */
  private getParsedMetadata(): ODataMetadata | null {
    if (this.parsedMetadata) {
      return this.parsedMetadata;
    }

    // Try to parse from x-odata-metadata-xml if available
    const metadataXml = this.api['x-odata-metadata-xml'];
    if (metadataXml) {
      try {
        this.parsedMetadata = parseODataMetadata(metadataXml);
        return this.parsedMetadata;
      } catch (error) {
        console.error('Failed to parse OData metadata:', error);
      }
    }

    // Fallback to legacy x-odata-metadata structure if parsing fails
    return null;
  }

  /**
   * Check if API is OData
   */
  isSupported(api: any): boolean {
    return api?.['x-ibm-configuration']?.type === 'odata';
  }

  /**
   * Extract OData service root URLs
   */
  getEndpoints() {
    let endpoints: any = [];

    // Check for endpoint property
    if (this.api.endpoint) {
      endpoints = [{ url: this.api.endpoint }];
    }
    // Check for x-ibm-endpoints (similar to OpenApiV2)
    else if (this.api['x-ibm-endpoints'] && this.api['x-ibm-endpoints'].length > 0) {
      endpoints = this.api['x-ibm-endpoints'].map((endpoint: any) => ({
        url: endpoint.url,
        types: this.getEndpointTypes(endpoint.type),
        variables: endpoint.variables
      }));
    }
    // Check for x-ibm-configuration.servers
    else if (get(this.api, 'x-ibm-configuration.servers', []).length > 0) {
      endpoints = this.api['x-ibm-configuration'].servers.map((server: any) => ({
        url: server.url,
        types: this.getEndpointTypes(server.type),
        variables: server.variables
      }));
    }
    // Check for OpenAPI 3.x servers
    else if (this.api.servers && this.api.servers.length > 0) {
      endpoints = this.api.servers.map((server: any) => ({
        url: server.url,
        types: [],
        variables: server.variables
      }));
    }
    // Fallback: construct from host/basePath/schemes (like OpenApiV2)
    else if (this.api.swagger) {
      let host = '';

      if (this.api.host) {
        host = this.api.host;
      } else {
        host = window.location.host;
      }
      const baseEndpoint = `://${host}`;
      if (this.api.schemes) {
        for (let i = 0; i < this.api.schemes.length; i += 1) {
          let endpoint = this.api.schemes[i] + baseEndpoint;
          if (this.api.basePath) {
            endpoint += this.api.basePath;
          }
          endpoints.push({ url: endpoint, types: null });
        }
      } else {
        let endpoint = `https${baseEndpoint}`;
        if (this.api.basePath) {
          endpoint += this.api.basePath;
        }
        endpoints.push({ url: endpoint, types: null });
      }
    }

    // Resolve relative URLs to absolute URLs
    endpoints.forEach((ep: any) => {
      ep.url = this.resolveRelativeUrl(ep.url);
    });

    return endpoints;
  }

  /**
   * Parse entity sets from $metadata
   * Returns synchronously from cache, triggers async fetch if needed
   */
  getEntitySets() {
    // Trigger async fetch if metadata not loaded (non-blocking)
    if (!this.parsedMetadata && !this.metadataFetchPromise) {
      this.fetchAndParseMetadata().catch(err => {
        console.error('[ODataApi] Background metadata fetch failed:', err);
      });
    }

    // Try parsed metadata first (synchronous)
    const parsed = this.getParsedMetadata();
    if (parsed) {
      return parsed.entitySets.map((es) => {
        // Find the entity type for this entity set
        const entityType = parsed.entityTypes.find((et) =>
          es.entityType === `${parsed.namespace}.${et.name}` ||
          es.entityType === et.name
        );

        return {
          name: es.name,
          entityType: es.entityType,
          properties: entityType?.properties || [],
          navigationProperties: entityType?.navigationProperties || [],
          keyProperties: entityType?.key?.map((keyName) =>
            entityType.properties.find((p) => p.name === keyName)
          ).filter(Boolean) || []
        };
      });
    }

    // Fallback to legacy format
    const metadata = get(this.api, 'x-odata-metadata', {});
    return metadata.entitySets || [];
  }

  /**
   * Extract OData operations (functions/actions)
   */
  getOperations() {
    // Try parsed metadata first
    const parsed = this.getParsedMetadata();
    if (parsed) {
      const operations: any[] = [];
      
      // Add functions
      parsed.functions.forEach((func) => {
        operations.push({
          name: func.name,
          type: 'function',
          isBound: func.isBound,
          isComposable: func.isComposable,
          parameters: func.parameters,
          returnType: func.returnType?.type,
          entitySetPath: func.entitySetPath
        });
      });
      
      // Add actions
      parsed.actions.forEach((action) => {
        operations.push({
          name: action.name,
          type: 'action',
          isBound: action.isBound,
          parameters: action.parameters,
          returnType: action.returnType?.type,
          entitySetPath: action.entitySetPath
        });
      });
      
      return operations;
    }

    // Fallback to legacy format
    const metadata = get(this.api, 'x-odata-metadata', {});
    return metadata.operations || [];
  }

  /**
   * Get navigation properties for entity relationships
   */
  getNavigationProperties(entitySetName: string) {
    const entitySets = this.getEntitySets();
    const entitySet = entitySets.find((e: any) => e.name === entitySetName);
    return entitySet?.navigationProperties || [];
  }

  /**
   * Get metadata XML string
   */
  getMetadataXml(): string | null {
    return this.api['x-odata-metadata-xml'] || null;
  }

  /**
   * Get metadata URL
   * Returns absolute URL for fetching metadata
   */
  getMetadataUrl(): string | null {
    const metadataUrl = this.api['x-odata-metadata-url'];
    
    if (metadataUrl) {
      // If it's already an absolute URL, return it
      if (metadataUrl.startsWith('http://') || metadataUrl.startsWith('https://')) {
        return metadataUrl;
      }
      
      // If it's relative, construct absolute URL from service root
      const serviceRoot = this.getServiceRoot();
      if (serviceRoot) {
        // Remove trailing slash from service root if present
        const root = serviceRoot.endsWith('/') ? serviceRoot.slice(0, -1) : serviceRoot;
        // Add leading slash to metadata URL if not present
        const path = metadataUrl.startsWith('/') ? metadataUrl : `/${metadataUrl}`;
        return `${root}${path}`;
      }
    }

    // Construct from service root with default $metadata path
    const serviceRoot = this.getServiceRoot();
    return serviceRoot ? `${serviceRoot}/$metadata` : null;
  }

  /**
   * Enable Try-It functionality
   */
  isTestable(): boolean {
    return true;
  }

  /**
   * Get OData version
   */
  getODataVersion() {
    return get(this.api, 'x-odata-metadata.version', DEFAULT_ODATA_VERSION);
  }

  /**
   * Get service root URL
   */
  getServiceRoot() {
    const endpoints = this.getEndpoints();
    return endpoints.length > 0 ? endpoints[0].url : '';
  }

  /**
   * Returns all schema definitions
   * For OData, returns definitions if they exist in the API document
   */
  getSchemas() {
    // If definitions already exist in the API document, use them directly
    if (this.api.definitions && Object.keys(this.api.definitions).length > 0) {
      return this.api.definitions;
    }

    // For OData without explicit definitions, return a placeholder
    // This ensures the Definitions link appears but without sub-items
    return { _odata_placeholder: { type: 'object' } };
  }

  /**
   * Returns all schema definitions with their correct place in the object
   */
  getSchemasFullPath() {
    return { definitions: this.getSchemas() };
  }

  /**
   * Get the root of the definitions from the Object returned by getSchemasFullPath()
   */
  getSchemasRoot(schemasFullPath: any) {
    return schemasFullPath?.definitions || null;
  }

  /**
   * Convert OData entity/complex type to JSON Schema format
   */
  private convertODataTypeToSchema(odataType: any) {
    const schema: any = {
      type: 'object',
      properties: {}
    };

    if (odataType.properties && Array.isArray(odataType.properties)) {
      odataType.properties.forEach((prop: any) => {
        schema.properties[prop.name] = this.convertODataPropertyToSchema(prop);
      });
    }

    if (odataType.navigationProperties && Array.isArray(odataType.navigationProperties)) {
      odataType.navigationProperties.forEach((navProp: any) => {
        schema.properties[navProp.name] = {
          type: 'object',
          description: `Navigation property: ${navProp.type}`
        };
      });
    }

    // Add required fields based on nullable property
    const required = odataType.properties
      ?.filter((prop: any) => prop.nullable === false)
      .map((prop: any) => prop.name);
    
    if (required && required.length > 0) {
      schema.required = required;
    }

    return schema;
  }

  /**
   * Convert OData property to JSON Schema property
   */
  private convertODataPropertyToSchema(prop: any) {
    const schema: any = {};

    // Handle collection types
    if (prop.type?.startsWith('Collection(')) {
      schema.type = 'array';
      const itemType = prop.type.match(/Collection\((.*)\)/)?.[1];
      if (itemType) {
        schema.items = this.mapODataTypeToJsonSchema(itemType);
      }
    } else {
      Object.assign(schema, this.mapODataTypeToJsonSchema(prop.type));
    }

    if (prop.description) {
      schema.description = prop.description;
    }

    return schema;
  }

  /**
   * Convert OData enum type to JSON Schema format
   */
  private convertODataEnumToSchema(enumType: any) {
    const schema: any = {
      type: 'string'
    };

    if (enumType.members && Array.isArray(enumType.members)) {
      schema.enum = enumType.members.map((member: any) => member.name || member);
    }

    return schema;
  }

  /**
   * Map OData primitive types to JSON Schema types
   */
  private mapODataTypeToJsonSchema(odataType: string) {
    const typeMap: any = {
      'Edm.String': { type: 'string' },
      'Edm.Int16': { type: 'integer', format: 'int32' },
      'Edm.Int32': { type: 'integer', format: 'int32' },
      'Edm.Int64': { type: 'integer', format: 'int64' },
      'Edm.Single': { type: 'number', format: 'float' },
      'Edm.Double': { type: 'number', format: 'double' },
      'Edm.Decimal': { type: 'number' },
      'Edm.Boolean': { type: 'boolean' },
      'Edm.Date': { type: 'string', format: 'date' },
      'Edm.DateTimeOffset': { type: 'string', format: 'date-time' },
      'Edm.TimeOfDay': { type: 'string', format: 'time' },
      'Edm.Duration': { type: 'string' },
      'Edm.Guid': { type: 'string', format: 'uuid' },
      'Edm.Binary': { type: 'string', format: 'binary' },
      'Edm.Byte': { type: 'integer' },
      'Edm.SByte': { type: 'integer' },
      'Edm.GeographyPoint': { type: 'object' },
      'Edm.Stream': { type: 'string', format: 'binary' }
    };

    // Check if it's a primitive type
    if (typeMap[odataType]) {
      return typeMap[odataType];
    }

    // If it's a complex type reference, return object with $ref
    if (odataType && odataType.includes('.')) {
      const typeName = odataType.split('.').pop();
      return {
        $ref: `#/definitions/${typeName}`
      };
    }

    // Default to object for unknown types
    return { type: 'object' };
  }

  /**
   * Get security definitions from the API
   */
  getSecurityDefinitions() {
    return this.api.securityDefinitions || {};
  }

  /**
   * Get channel - stub for routing compatibility
   * OData doesn't use channels, but routing may call this
   */
  // eslint-disable-next-line no-unused-vars
  getChannel(_channelName: string) {
    return null;
  }

  /**
   * Get description - stub for routing compatibility
   * Returns entity set description if available
   */
  getDescription(entitySetName: string) {
    const entitySets = this.getEntitySets();
    const entitySet = entitySets.find((e: any) => e.name === entitySetName);
    return entitySet?.description || '';
  }

  /**
   * Get markup type for documentation rendering
   */
  getMarkupType() {
    return MarkupTypes.markdown;
  }

  /**
   * Get content types for OData operations
   * OData typically uses application/json
   */
  getContentTypes(operation: any, api: any) {
    // Check x-odata-metadata.contentTypes first
    const metadataContentTypes = get(api, 'x-odata-metadata.contentTypes');
    if (metadataContentTypes && Array.isArray(metadataContentTypes) && metadataContentTypes.length > 0) {
      return metadataContentTypes;
    }

    // Check operation-level content types (consumes in OpenAPI v2)
    if (operation?.consumes && operation.consumes.length > 0) {
      return operation.consumes;
    }

    // Check API-level content types
    if (api?.consumes && api.consumes.length > 0) {
      return api.consumes;
    }

    // Fall back to default
    return ['application/json'];
  }

  /**
   * Get accept types for OData operations
   * OData typically accepts application/json, but $metadata requires application/xml
   */
  getAccepts(operation: any, api: any) {
    // Check x-odata-metadata.acceptTypes first
    const metadataAcceptTypes = get(api, 'x-odata-metadata.acceptTypes');
    if (metadataAcceptTypes && Array.isArray(metadataAcceptTypes) && metadataAcceptTypes.length > 0) {
      return metadataAcceptTypes;
    }

    // Check operation-level accept types (produces in OpenAPI v2)
    if (operation?.produces && operation.produces.length > 0) {
      return operation.produces;
    }

    // Check API-level accept types
    if (api?.produces && api.produces.length > 0) {
      return api.produces;
    }

    // Fall back to hardcoded defaults based on operation type
    const path = operation?.path || '';
    if (path.includes('$metadata')) {
      return ['application/xml'];
    }
    return ['application/json'];
  }

  /**
   * Get OData query parameters for the overview Try It section
   * Returns header parameters for authentication and query parameters for OData options
   * Note: This is used by the overview Try It section, not per-operation
   */
  getODataQueryParameters(entitySetName?: string) {
    const parameters: any = {};
    
    // Add authentication header parameters if security is defined
    const securityDefs = this.getSecurityDefinitions();
    if (securityDefs && Object.keys(securityDefs).length > 0) {
      Object.keys(securityDefs).forEach((key) => {
        const secDef = securityDefs[key];
        if (secDef.type === 'apiKey' && secDef.in === 'header') {
          parameters[secDef.name] = {
            name: secDef.name,
            in: 'header',
            type: 'string',
            description: secDef.description || `API Key for ${key}`,
            required: false
          };
        }
      });
    }
    
    // Extract OData query parameters from API specification
    let odataParams = [];
    
    // Check x-odata-metadata.queryParameters first
    if (this.api['x-odata-metadata']?.queryParameters) {
      odataParams = this.api['x-odata-metadata'].queryParameters;
    }
    // Then check paths parameters for the entity set (GET operation only)
    else if (entitySetName && this.api.paths) {
      const entitySetPath = `/${entitySetName}`;
      if (this.api.paths[entitySetPath]?.get?.parameters) {
        odataParams = this.api.paths[entitySetPath].get.parameters.filter((p: any) => p.in === 'query');
      }
    }
    
    // Use extracted parameters or fallback to standard OData defaults for GET operations
    if (odataParams.length > 0) {
      odataParams.forEach((param: any) => {
        parameters[param.name] = {
          name: param.name,
          in: param.in || 'query',
          type: param.type || param.schema?.type || 'string',
          description: param.description || '',
          required: param.required || false
        };
      });
    } else {
      // Fallback to standard OData query parameters (for GET operations)
      const defaultParams = [
        { name: '$filter', description: 'Filter the results using OData filter syntax' },
        { name: '$select', description: 'Select specific properties to return' },
        { name: '$expand', description: 'Expand related entities' },
        { name: '$orderby', description: 'Order the results' },
        { name: '$top', description: 'Limit the number of results', type: 'integer' },
        { name: '$skip', description: 'Skip a number of results', type: 'integer' },
        { name: '$count', description: 'Include count of matching results', type: 'boolean' }
      ];
      
      defaultParams.forEach((param) => {
        parameters[param.name] = {
          name: param.name,
          in: 'query',
          type: param.type || 'string',
          description: param.description,
          required: false
        };
      });
    }
    
    // Add key parameter if entity set is specified
    if (entitySetName) {
      const entitySets = this.getEntitySets();
      const entitySet = entitySets.find((e: any) => e.name === entitySetName);
      if (entitySet && entitySet.keyProperties && entitySet.keyProperties.length > 0) {
        const keyProp = entitySet.keyProperties[0];
        parameters.key = {
          name: 'key',
          in: 'path',
          type: keyProp.type || 'string',
          description: `Key value for ${entitySetName} (${keyProp.name})`,
          required: false
        };
      }
    }
    
    return parameters;
  }

  /**
   * Override getParameters to filter out OData query parameters for non-GET operations
   * In OData, query parameters like $filter, $select, etc. only apply to GET requests
   */
  getParameters(operation: any, path: any, contentType: any, openApi: any) {
    // Get parameters from parent class
    const parameters = super.getParameters(operation, path, contentType, openApi);
    
    if (!parameters || !operation) {
      return parameters;
    }

    // If this is not a GET operation, filter out OData system query parameters
    const method = operation['x-method'] || operation.method;
    if (method && method.toLowerCase() !== 'get') {
      const filteredParams: any = {};
      
      Object.keys(parameters).forEach((paramName) => {
        const param = parameters[paramName];
        
        // Keep the parameter if it's NOT an OData system query parameter
        // OData system query parameters start with $
        if (param.in !== 'query' || !param.name?.startsWith('$')) {
          filteredParams[paramName] = param;
        }
      });
      
      return filteredParams;
    }
    
    return parameters;
  }

  /**
   * AsyncAPI compatibility methods - OData doesn't use these concepts
   * These are stubs to prevent errors when routing tries to call them
   */
  // eslint-disable-next-line no-unused-vars
  getChannelBindings(_channelName: string) {
    return null;
  }

  // eslint-disable-next-line no-unused-vars
  getMessage(_channelName: string, _operation: string) {
    return null;
  }

  // eslint-disable-next-line no-unused-vars
  getMessageBindings(_message: any) {
    return null;
  }

  // eslint-disable-next-line no-unused-vars
  getServerBindings(_serverName: any) {
    return null;
  }
}

export { ODataApi };
