import JavaKafkaCodeSnippet from './JavaKafkaCodeSnippet.ts';

class KafkaConsoleConsumerCodeSnippet extends JavaKafkaCodeSnippet {
  // The only reason for using a byte deserializer is for schemas, which aren't supported by the console consumer
  // So use string instead to show the JSON representation
  getByteDeserializer() {
    return {
      deserializerClass: 'org.apache.kafka.common.serialization.StringDeserializer',
      deserializerType: 'String'
    };
  }
}

export default KafkaConsoleConsumerCodeSnippet;
