/* eslint-disable prefer-destructuring */

import React, { useState, useEffect, ChangeEvent } from 'react';
import { get } from 'lodash';
import { useTranslation } from 'react-i18next';
import { Accordion, AccordionItem, Select, SelectItem, TextInput } from '@carbon/react';
import { findFirstAppWithAccess } from '../utils/common';
import classNames from 'classnames';
import TestToolIdentification from './TestToolIdentification';
import TestToolUserCredentials from './TestToolUserCredentials';
import TestToolDigestAuth from './TestToolDigestAuth';
import TestToolHobaAuth from './TestToolHobaAuth';
import TestToolMutualAuth from './TestToolMutualAuth';
import TestToolNegotiateAuth from './TestToolNegotiateAuth';
import TestToolVapidAuth from './TestToolVapidAuth';
import TestToolScramShaAuth from './TestToolScramShaAuth';
import TestToolSecurityFlows from './TestToolSecurityFlows';
import TestToolScopes from './TestToolScopes';
import TestToolAccessCode from './TestToolAccessCode';
import TestToolAccessToken from './TestToolAccessToken';
import TestToolRedirectUri from './TestToolRedirectUri';
import TestToolRefreshToken from './TestToolRefreshToken';
import TestToolOidcDiscovery from './TestToolOidcDiscovery';

type IdentificationType = {
  clientID: string | null;
  clientSecret: string;
  redirectUri: string | null;
  redirectUris: string[];
  externalApiKeys: Record<string, any>;
}

type UserCredentialsType = {
  username: string | undefined;
  password: string | undefined;
}

type HttpDigestAuthType = {
  digestUsername: string | null;
  digestRealm: string;
  digestNonce: string;
  digestOpaque: string;
  digestResponse: string;
}

type HttpMutualAuthType = {
  mutualVersion: string;
  mutualSid: string;
  mutualNonce: string;
  mutualVkc: string;
}

type HttpNegotiateAuthType = {
  negotiateGssapiData: string;
}

type HttpHobaAuthType = {
  hobaKeyIdentifier: string;
  hobaChallenge: string;
  hobaNonce: string;
  hobaSignature: string;
}

type HttpVapidAuthType = {
  vapidJSONWebToken: string;
  vapidJSONWebKey: string;
}

type HttpScramShaAuthType = {
  scramSessionId: string;
  scramEncryptedCreds: string;
}

type AuthTokenType = {
  code: string;
  access_token: string;
  refresh_token?: string;
}

type FlagsType = {
  selectedAuthUrl?: string | string[];
  selectedTokenUrl?: string | string[];
  selectedRefreshUrl?: string | string[];
  oauthAuthUrl?: string | string[];
  oauthTokenUrl?: string | string[];
  oauthRefreshUrl?: string | string[];
  oauthFlow?: string;
  openIdConnectUrl?: string;
  requiresIdentificationSection?: boolean;
  requiresAuthorizationSection?: boolean;
  requiresUserCredentials?: boolean;
  requiresDigestAuth?: boolean;
  requiresHobaAuth?: boolean;
  requiresMutualAuth?: boolean;
  requiresNegotiateAuth?: boolean;
  requiresVapidAuth?: boolean;
  requiresScramShaAuth?: boolean;
  requiresOauth?: boolean;
  requiresHttpBearerToken?: boolean;
  requiresRefreshToken?: boolean;
  requiresRedirectUri?: boolean;
  oauthScopes?: string[];
  oauthFlowsConfig?: Record<string, any>;
  [key: string]: any;
}

type ConfigType = {
  flags?: FlagsType;
  securityFlows: Record<string, any>;
}

type AppType = {
  credentials: Array<{
    client_id: string;
  }>;
  redirectUri?: string | string[];
}

type OptionsType = {
  optimiseOauthUX?: boolean;
  authentication?: {
    username?: string;
    password?: string;
  };
}

type TestToolSecurityProps = {
  config: ConfigType;
  options: OptionsType;
  apps: AppType[];
  isEnforced: boolean;
  onChange?: Function;
  endpoint: any;
}

type StateType = {
  flags: FlagsType;
  scopes: Record<string, any>;
  identification: IdentificationType;
  userCredentials: UserCredentialsType;
  authToken: AuthTokenType;
  httpBearerToken: string;
  httpDigestAuth: HttpDigestAuthType;
  httpMutualAuth: HttpMutualAuthType;
  httpNegotiateAuth: HttpNegotiateAuthType;
  httpHobaAuth: HttpHobaAuthType;
  httpVapidAuth: HttpVapidAuthType;
  httpScramShaAuth: HttpScramShaAuthType;
  removeFields: boolean;
  currentFlow: string;
}

function TestToolSecurity({ config, options, apps, isEnforced, onChange, endpoint: propsEndpoint }: TestToolSecurityProps) {
  const [flags, setFlags] = useState<FlagsType>({});
  const [scopes, setScopes] = useState<Record<string, any>>({});
  const [endpoint, setEndpoint] = useState<any>({});
  const { t } = useTranslation();
  const [identification, setIdentification] = useState<IdentificationType>({
    clientID: null,
    clientSecret: '',
    redirectUri: null,
    redirectUris: [],
    externalApiKeys: {}
  });
  const [userCredentials, setUserCredentials] = useState<UserCredentialsType>({
    username: undefined,
    password: undefined
  });
  const [httpBearerToken, setHttpBearerToken] = useState<string>('');
  const [httpDigestAuth, setHttpDigestAuth] = useState<HttpDigestAuthType>({
    digestUsername: null,
    digestRealm: '',
    digestNonce: '',
    digestOpaque: '',
    digestResponse: ''
  });
  const [httpMutualAuth, setHttpMutualAuth] = useState<HttpMutualAuthType>({
    mutualVersion: '',
    mutualSid: '',
    mutualNonce: '',
    mutualVkc: ''
  });
  const [httpNegotiateAuth, setHttpNegotiateAuth] = useState<HttpNegotiateAuthType>({
    negotiateGssapiData: ''
  });
  const [httpHobaAuth, setHttpHobaAuth] = useState<HttpHobaAuthType>({
    hobaKeyIdentifier: '',
    hobaChallenge: '',
    hobaNonce: '',
    hobaSignature: ''
  });
  const [httpVapidAuth, setHttpVapidAuth] = useState<HttpVapidAuthType>({
    vapidJSONWebToken: '',
    vapidJSONWebKey: ''
  });
  const [httpScramShaAuth, setHttpScramShaAuth] = useState<HttpScramShaAuthType>({
    scramSessionId: '',
    scramEncryptedCreds: ''
  });

  const [removeFields, setRemoveFields] = useState<boolean>(false);
  const [currentFlow, setCurrentFlow] = useState<string>('login');
  const [authToken, setAuthToken] = useState<AuthTokenType>({
    code: '',
    access_token: ''
  });

  const changeAuthorizationUrl = (evt: ChangeEvent<HTMLSelectElement>) => {
    const newFlags = { ...flags, selectedAuthUrl: get(evt, 'target.value') };
    setFlags(newFlags);
    if (onChange && typeof onChange === 'function') {
      onChange({ flags: newFlags });
    }
  };
  const changeTokenUrl = (evt: ChangeEvent<HTMLSelectElement>) => {
    const newFlags = { ...flags, selectedTokenUrl: get(evt, 'target.value') };
    setFlags(newFlags);
    if (onChange && typeof onChange === 'function') {
      onChange({ flags: newFlags });
    }
  };
  const changeRefreshUrl = (evt: ChangeEvent<HTMLSelectElement>) => {
    const newFlags = { ...flags, selectedRefreshUrl: get(evt, 'target.value') };
    setFlags(newFlags);
    if (onChange && typeof onChange === 'function') {
      onChange({ flags: newFlags });
    }
  };

  useEffect(() => {
    if (onChange && typeof onChange === 'function') {
      onChange({ identification });
    }
  }, [identification, onChange]);

  useEffect(() => {
    if (config) {
      let newFlags = flags;
      if (config.flags) {
        if (!flags || Object.keys(flags).length === 0 || endpoint !== propsEndpoint) {
          newFlags = config.flags;
        }
      }
      if (!currentFlow || (newFlags !== flags && Object.keys(newFlags).length !== 0)) {
        const initialFlow = Object.keys(config.securityFlows)[0];
        setCurrentFlow(initialFlow);
      }
      // Only set default selection if not already selected OR endpoint changed
      if (newFlags.oauthAuthUrl && (!newFlags.selectedAuthUrl || endpoint !== propsEndpoint)) {
        newFlags.selectedAuthUrl = newFlags.oauthAuthUrl;
      }
      if (newFlags.oauthTokenUrl && (!newFlags.selectedTokenUrl || endpoint !== propsEndpoint)) {
        newFlags.selectedTokenUrl = newFlags.oauthTokenUrl;
      }
      if (newFlags.oauthRefreshUrl && (!newFlags.selectedRefreshUrl || endpoint !== propsEndpoint)) {
        newFlags.selectedRefreshUrl = newFlags.oauthRefreshUrl;
      }
      if (Array.isArray(newFlags.selectedAuthUrl) && newFlags.selectedAuthUrl.length > 0) {
        newFlags.selectedAuthUrl = newFlags.selectedAuthUrl[0];
      }
      if (Array.isArray(newFlags.selectedTokenUrl) && newFlags.selectedTokenUrl.length > 0) {
        newFlags.selectedTokenUrl = newFlags.selectedTokenUrl[0];
      }
      if (Array.isArray(newFlags.selectedRefreshUrl) && newFlags.selectedRefreshUrl.length > 0) {
        newFlags.selectedRefreshUrl = newFlags.selectedRefreshUrl[0];
      }
      if (
        ((newFlags.oauthFlow === 'accessCode' || newFlags.oauthFlow === 'authorizationCode' || newFlags.oauthFlow === 'implicit') && options.optimiseOauthUX) ||
        newFlags.openIdConnectUrl
      ) {
        setRemoveFields(true);
      } else {
        setRemoveFields(false);
      }
      if (Object.keys(newFlags).length !== 0) {
        setFlags(newFlags);
        if (onChange && typeof onChange === 'function') {
          onChange({ flags: newFlags });
        }
      }
    }
    if (endpoint !== propsEndpoint) {
      setEndpoint(propsEndpoint);
    }

    if (identification.clientID === null && apps && apps.length > 0) {
      const initialApp = findFirstAppWithAccess(apps);
      if (initialApp && initialApp.credentials && initialApp.credentials.length > 0) {
        const initialIdentification: Partial<IdentificationType> = {};

        initialIdentification.clientID = initialApp.credentials[0].client_id;
        initialIdentification.redirectUris = [''];

        const initialRedirectUri = initialApp.redirectUri;
        if (typeof initialRedirectUri === 'string') {
          initialIdentification.redirectUris[0] = initialRedirectUri;
        } else if (initialRedirectUri && Array.isArray(initialRedirectUri) && initialRedirectUri.length > 0) {
          initialIdentification.redirectUris = initialRedirectUri;
        }
        initialIdentification.redirectUri = initialIdentification.redirectUris[0];

        initialIdentification.externalApiKeys = {};

        setIdentification(initialIdentification as IdentificationType);
      }
    }

    if (!userCredentials.username && options.authentication) {
      const initialUserCreds: Partial<UserCredentialsType> = {};

      initialUserCreds.username = options.authentication.username ? options.authentication.username : undefined;
      initialUserCreds.password = options.authentication.password ? options.authentication.password : undefined;

      setUserCredentials(initialUserCreds as UserCredentialsType);
      if (onChange && typeof onChange === 'function') {
        onChange({ userCredentials: initialUserCreds });
      }
    }
  }, [
    apps,
    config,
    currentFlow,
    endpoint,
    flags,
    identification.clientID,
    onChange,
    options.authentication,
    options.optimiseOauthUX,
    propsEndpoint,
    userCredentials.username
  ]);

  const changeSecurityFlow = (flow: string) => {
    const selectedFlags = config.securityFlows[flow].config;

    const newFlags = { ...flags, ...selectedFlags };
    newFlags.selectedAuthUrl = selectedFlags.oauthAuthUrl;
    newFlags.selectedTokenUrl = selectedFlags.oauthTokenUrl;
    newFlags.selectedRefreshUrl = selectedFlags.oauthRefreshUrl;
    if (Array.isArray(newFlags.selectedAuthUrl) && newFlags.selectedAuthUrl.length > 0) {
      newFlags.selectedAuthUrl = newFlags.selectedAuthUrl[0];
    }
    if (Array.isArray(newFlags.selectedTokenUrl) && newFlags.selectedTokenUrl.length > 0) {
      newFlags.selectedTokenUrl = newFlags.selectedTokenUrl[0];
    }
    if (Array.isArray(newFlags.selectedRefreshUrl) && newFlags.selectedRefreshUrl.length > 0) {
      newFlags.selectedRefreshUrl = newFlags.selectedRefreshUrl[0];
    }

    if (
      ((newFlags.oauthFlow === 'accessCode' || newFlags.oauthFlow === 'authorizationCode' || newFlags.oauthFlow === 'implicit') && options.optimiseOauthUX) ||
      newFlags.openIdConnectUrl
    ) {
      setRemoveFields(true);
    } else {
      setRemoveFields(false);
    }
    setFlags(newFlags);
    if (onChange && typeof onChange === 'function') {
      onChange({ flags: newFlags });
    }
    setCurrentFlow(flow);
  };

  const changeIdentificationHandler = (update: Partial<IdentificationType>) => {
    const creds = { ...identification, ...update };
    setIdentification(creds);
    if (onChange && typeof onChange === 'function') {
      onChange({ identification: creds });
    }
  };

  const changeHttpDigestAuthHandler = (update: Partial<HttpDigestAuthType>) => {
    const creds = { ...httpDigestAuth, ...update };
    setHttpDigestAuth(creds);
    if (onChange && typeof onChange === 'function') {
      onChange({ httpDigestAuth: creds });
    }
  };

  const changeHttpHobaAuthHandler = (update: Partial<HttpHobaAuthType>) => {
    const creds = { ...httpHobaAuth, ...update };
    setHttpHobaAuth(creds);
    if (onChange && typeof onChange === 'function') {
      onChange({ httpHobaAuth: creds });
    }
  };

  const changeHttpMutualAuthHandler = (update: Partial<HttpMutualAuthType>) => {
    const creds = { ...httpMutualAuth, ...update };
    setHttpMutualAuth(creds);
    if (onChange && typeof onChange === 'function') {
      onChange({ httpMutualAuth: creds });
    }
  };

  const changeHttpNegotiateAuthHandler = (update: Partial<HttpNegotiateAuthType>) => {
    const creds = { ...httpNegotiateAuth, ...update };
    setHttpNegotiateAuth(creds);
    if (onChange && typeof onChange === 'function') {
      onChange({ httpNegotiateAuth: creds });
    }
  };

  const changeHttpVapidAuthHandler = (update: Partial<HttpVapidAuthType>) => {
    const creds = { ...httpVapidAuth, ...update };
    setHttpVapidAuth(creds);
    if (onChange && typeof onChange === 'function') {
      onChange({ httpVapidAuth: creds });
    }
  };
  const changeHttpScramShaAuthHandler = (update: Partial<HttpScramShaAuthType>) => {
    const creds = { ...httpScramShaAuth, ...update };
    setHttpScramShaAuth(creds);
    if (onChange && typeof onChange === 'function') {
      onChange({ httpScramShaAuth: creds });
    }
  };

  const changeUserCredentialsHandler = (update: Partial<UserCredentialsType>) => {
    const creds = { ...userCredentials, ...update };
    setUserCredentials(creds);
    if (onChange && typeof onChange === 'function') {
      onChange({ userCredentials: creds });
    }
  };

  const changeSecurityOauthFlow = (oauthFlow: string) => {
    const selectedFlags = config.securityFlows[currentFlow].config.oauthFlowsConfig[oauthFlow];
    selectedFlags.oauthFlowsConfig = config.securityFlows[currentFlow].config.oauthFlowsConfig;
    setFlags(selectedFlags);
    if (onChange && typeof onChange === 'function') {
      onChange({ flags: selectedFlags });
    }
  };

  const changeScopes = (scopes: Record<string, any>) => {
    setScopes(scopes);
  };

  const handleAuthToken = (newAuthToken: Partial<AuthTokenType>) => {
    const newToken = { ...authToken, ...newAuthToken };
    setAuthToken(newToken);
    if (onChange && typeof onChange === 'function') {
      onChange({ authToken: newToken });
    }
  };

  const handleHttpBearerChange = (event: ChangeEvent<HTMLInputElement>) => {
    setHttpBearerToken(event.target.value);
    if (onChange && typeof onChange === 'function') {
      onChange({ httpBearerToken: event.target.value });
    }
  };

  const shouldDisplay =
    (flags && (flags.requiresIdentificationSection || flags.requiresAuthorizationSection)) ||
    (config && config.securityFlows && Object.keys(config.securityFlows).length > 1);
  const stateToPass: StateType = {
    flags,
    scopes,
    identification,
    userCredentials,
    authToken,
    httpBearerToken,
    httpDigestAuth,
    httpMutualAuth,
    httpNegotiateAuth,
    httpHobaAuth,
    httpVapidAuth,
    httpScramShaAuth,
    removeFields,
    currentFlow
  };

  if (shouldDisplay) {
    return (
      <div className="testToolSection">
        <h3 className="labelText">{t('security')}</h3>
        <div className="testToolSecurity">
          {config && config.securityFlows && Object.keys(config.securityFlows).length > 1 && (
            <div className="securityFlow">
              <TestToolSecurityFlows flows={config.securityFlows} onChange={changeSecurityFlow} currentFlow={currentFlow} />
            </div>
          )}

          {flags.requiresIdentificationSection && (
            <TestToolIdentification
              flags={flags}
              options={options}
              externalApiKeys={identification.externalApiKeys}
              apps={apps as any}
              onChange={changeIdentificationHandler as any}
              isEnforced={isEnforced}
              onCopyClientIdCallback={() => navigator.clipboard.writeText(identification.clientID || '')}
            />
          )}
          {flags.requiresAuthorizationSection && (
            <Accordion className="testToolAuthorization" align="start">
              <AccordionItem className="testToolAuthorizationInput" title={t('authorization')} open>
                {flags.oauthFlowsConfig && Object.keys(flags.oauthFlowsConfig).length > 1 && (
                  <div className="securityFlow">
                    <TestToolSecurityFlows flows={flags.oauthFlowsConfig} onChange={changeSecurityOauthFlow} currentFlow={null} />
                  </div>
                )}
                {flags.requiresUserCredentials && <TestToolUserCredentials userCreds={userCredentials} onChange={changeUserCredentialsHandler} />}
                {flags.requiresDigestAuth && <TestToolDigestAuth digestCreds={httpDigestAuth} onChange={changeHttpDigestAuthHandler} />}
                {flags.requiresHobaAuth && <TestToolHobaAuth hobaCreds={httpHobaAuth} onChange={changeHttpHobaAuthHandler} />}
                {flags.requiresMutualAuth && <TestToolMutualAuth mutualCreds={httpMutualAuth} onChange={changeHttpMutualAuthHandler} />}
                {flags.requiresNegotiateAuth && <TestToolNegotiateAuth negotiateCreds={httpNegotiateAuth} onChange={changeHttpNegotiateAuthHandler} />}
                {flags.requiresVapidAuth && <TestToolVapidAuth vapidCreds={httpVapidAuth} onChange={changeHttpVapidAuthHandler} />}
                {flags.requiresScramShaAuth && <TestToolScramShaAuth scramCreds={httpScramShaAuth} onChange={changeHttpScramShaAuthHandler} />}

                {flags.oauthScopes && flags.oauthScopes.length > 0 && !removeFields && (
                  <TestToolScopes scopes={flags.oauthScopes} onChange={changeScopes} />
                )}

                {flags.requiresRedirectUri && !removeFields && <TestToolRedirectUri value={identification} onChange={changeIdentificationHandler} />}
                {flags.oauthAuthUrl && flags.oauthAuthUrl.length > 0 && (
                  <div className="url authUrl">
                    <legend className="parameterName">
                      {t('explorer_authorization_url')}
                    </legend>
                    {Array.isArray(flags.oauthAuthUrl) && flags.oauthAuthUrl.length > 1 && (
                      <Select
                        hideLabel
                        data-testid="oauthAuthUrl-selector"
                        id="oauthAuthUrl-select"
                        value={flags.selectedAuthUrl as string}
                        onChange={changeAuthorizationUrl}
                      >
                        {flags.oauthAuthUrl.map((url) => (
                          <SelectItem data-testid="oauthAuthUrl-item" key={url} value={url} text={url} />
                        ))}
                      </Select>
                    )}
                    {(!Array.isArray(flags.oauthAuthUrl) || flags.oauthAuthUrl.length === 1) && <p className="parameterValue">{flags.oauthAuthUrl}</p>}
                  </div>
                )}
                {flags.oauthTokenUrl && (
                  <div className="url tokenUrl">
                    <legend className="parameterName">
                      {t('explorer_token_url')}
                    </legend>
                    {Array.isArray(flags.oauthTokenUrl) && flags.oauthTokenUrl.length > 1 && (
                      <Select hideLabel data-testid="oauthTokenUrl-selector" id="oauthTokenUrl-select" value={flags.selectedTokenUrl as string} onChange={changeTokenUrl}>
                        {flags.oauthTokenUrl.map((url) => (
                          <SelectItem data-testid="oauthTokenUrl-item" key={url} value={url} text={url} />
                        ))}
                      </Select>
                    )}
                    {(!Array.isArray(flags.oauthTokenUrl) || flags.oauthTokenUrl.length === 1) && <p className="parameterValue">{flags.oauthTokenUrl}</p>}
                  </div>
                )}
                {flags.oauthRefreshUrl && (
                  <div className="url refreshUrl">
                    <legend className="parameterName">
                      {t('explorer_refresh_url')}
                    </legend>
                    {Array.isArray(flags.oauthRefreshUrl) && flags.oauthRefreshUrl.length > 1 && (
                      <Select
                        hideLabel
                        data-testid="oauthRefreshUrl-selector"
                        id="oauthRefreshUrl-select"
                        value={flags.selectedRefreshUrl as string}
                        onChange={changeRefreshUrl}
                      >
                        {flags.oauthRefreshUrl.map((url) => (
                          <SelectItem data-testid="oauthRefreshUrl-item" key={url} value={url} text={url} />
                        ))}
                      </Select>
                    )}
                    {(!Array.isArray(flags.oauthRefreshUrl) || flags.oauthRefreshUrl.length === 1) && (
                      <p className="parameterValue">{flags.selectedRefreshUrl}</p>
                    )}
                  </div>
                )}

                {flags.openIdConnectUrl && (
                  <>
                    <TestToolOidcDiscovery config={stateToPass} onClick={handleAuthToken} />
                    <TestToolAccessToken config={stateToPass} onChange={handleAuthToken} />
                  </>
                )}

                {flags.requiresOauth && (
                  <div className={classNames('testToolOauth', { oauthFieldsRemoved: removeFields })}>
                    {(flags.oauthFlow === 'accessCode' || flags.oauthFlow === 'authorizationCode') && !removeFields && (
                      <TestToolAccessCode config={stateToPass} onChange={handleAuthToken} />
                    )}
                    <TestToolAccessToken config={stateToPass} onChange={handleAuthToken} />
                    {flags.requiresRefreshToken && authToken.refresh_token && <TestToolRefreshToken config={stateToPass} onClick={handleAuthToken} />}
                  </div>
                )}

                {flags.requiresHttpBearerToken && (
                  <div className="httpBearerToken" key="httpBearer">
                    <TextInput id="bearer" name="bearer" type="input" labelText="Bearer" onChange={handleHttpBearerChange} value={httpBearerToken} />
                  </div>
                )}
              </AccordionItem>
            </Accordion>
          )}
        </div>
      </div>
    );
  }
  return null;
}
export default TestToolSecurity;