import React, { JSX, useRef } from 'react';
import { useToggle } from 'usehooks-ts';
import { useTranslation } from 'react-i18next';
import { Loading } from '@carbon/react';
import { uniqueId } from 'lodash';
import classNames from 'classnames';
import CodeViewer from './CodeViewer.tsx';
import ExpandableDisplay from './ExpandableDisplay.tsx';
import { getHighlightClassForDependencies } from '../utils/CodeViewerLanguageMapper.ts';

type DependenciesProps = {
  generating?: boolean;
  dependencyContent: string;
  errorText?: string | null;
  activeCodeLanguage: string;
  label: string;
};

const Dependencies = ({ generating = false, dependencyContent = '', errorText = null, activeCodeLanguage = '', label }: DependenciesProps): JSX.Element => {
  const { t } = useTranslation();
  const [expanded, toggleExpanded] = useToggle(false);
  const copyRef = useRef(`code-snippet-${uniqueId()}`);
  const copyId = copyRef.current;

  const renderError = (errorText: string) => <div data-testid="snippet-error">{t('generator_error', { error: errorText })}</div>;

  const renderLoading = () => <Loading small withOverlay={false} data-testid="loading-icon" />;
  return (
    <div>
      {/* eslint-disable-next-line no-nested-ternary */}
      {errorText ? (
        renderError(errorText)
      ) : generating ? (
        renderLoading()
      ) : (
        <div>
          {label && (
            <h4 className="codeSnippetLabel" data-testid="dependencies-label">
              {label}
            </h4>
          )}
          <ExpandableDisplay copyableContent="" expanded={expanded} onExpand={toggleExpanded}>
            <CodeViewer
              data-copytarget={copyId}
              data-testid="generated-dependencies"
              codeLanguage={getHighlightClassForDependencies(activeCodeLanguage)}
              className={classNames('codeSnippetContent', { expanded })}
            >
              {dependencyContent}
            </CodeViewer>
          </ExpandableDisplay>
        </div>
      )}
    </div>
  );
};

export default Dependencies;
