import React from 'react';
import { Link, DefinitionTooltip } from '@carbon/react';
import classNames from 'classnames';
import { generateRandomTag } from '../utils/common';
import Markdown from './Markdown.tsx';
import MarkupTypes from '../utils/MarkupTypes.ts';
import { getBidiAlignAbsolute } from '../utils/getDirectionalAlign';

import { getTranslatedExtensions } from '../utils/translate';

type OperationTagProps = {
  tag: string,
  apiTags: any,
  markupType: MarkupTypes
}

const OperationTag = ({ tag, apiTags, markupType }: OperationTagProps) => {
  const tooltiptext = ({ tag, apiTags, markupType }: OperationTagProps) => (
    <div>
      {apiTags.tags[tag].description && (
        <Markdown className="tagDescription" data={getTranslatedExtensions(apiTags.tags[tag], 'description')} markupType={markupType} />
      )}
      {apiTags.tags[tag].externalDocs && apiTags.tags[tag].externalDocs.description && (
        <div className={classNames('tagtip', 'cds--tooltip__footer')}>
          <Link href={apiTags.tags[tag].externalDocs.url} target="_blank" rel="noopener noreferrer">
            {`${apiTags.tags[tag].externalDocs.description}: `}
            {apiTags.tags[tag].externalDocs.url}
          </Link>
        </div>
      )}
    </div>
  );

  let oaiTag;
  if (tag in apiTags.tags && ('description' in apiTags.tags[tag] || 'externalDocs' in apiTags.tags[tag])) {
    oaiTag = (
      <div className={classNames('cds--tag', generateRandomTag(tag))} data-floating-menu-container style={{ position: 'relative', float: getBidiAlignAbsolute('right') as 'right' || 'left' }}>
        <DefinitionTooltip
          triggerClassName={generateRandomTag(tag)}
          tabIndex={0}
          align={getBidiAlignAbsolute('left')}
          definition={tooltiptext({ tag, apiTags, markupType })}
        >
          {tag}
        </DefinitionTooltip>
      </div>
    );
  } else {
    oaiTag = (
      <span className={classNames('cds--tag', generateRandomTag(tag))} style={{ position: 'relative', float: getBidiAlignAbsolute('right') as 'right' || 'left' }}>
        {tag}
      </span>
    );
  }

  return oaiTag;
}

export default OperationTag;
