import React from 'react';
import { Dropdown, OnChangeData } from '@carbon/react';
import { get } from 'lodash';
import { useConfig } from '../contexts/config';
import { safeNavigate } from '../utils/urlValidator';

type ItemType = {
  url: string,
  text: string
}

const ExplorerHeader = () => {
  const config: any = useConfig();
  const title = config.options.headerTitle;
  
  const switchVersion = (data: OnChangeData<ItemType>) => {
    if (data.selectedItem?.url) {
      safeNavigate(data.selectedItem.url);
    }
  };
  
  const versions: Record<string, string> = get(config, 'options.versions');
  const versionsArray: Array<{ text: string; url: string }> = [];
  if (versions && Object.values(versions).length > 0) {
    Object.entries(versions).forEach(([key, value]) => {
      versionsArray.push({ text: key, url: value });
    });
  }

  return (
    <nav className="apic--explorer-header" data-testid="explorer-header">
      <div className="apic--explorer-header-brand-container">
        <div className="apic--brand-text">
          IBM <span className="bold">API</span> Connect
        </div>
        {versions && Object.values(versions).length > 0 && (
          <Dropdown
            titleText=""
            className="apic--brand-text dropdown"
            label={title}
            onChange={switchVersion}
            data-testid="version-picker"
            id="version-picker"
            itemToString={(item: ItemType | null) => (item ? item.text : '')}
            items={versionsArray}
          />
        )}
        {(!versions || Object.values(versions).length === 0) && <div className="apic--brand-text">{title}</div>}
      </div>
    </nav>
  );
}

export default ExplorerHeader;
