import React, { useEffect, useState } from 'react';
import { TextInput } from '@carbon/react';
import { useTranslation } from 'react-i18next';

type ScramCreds = {
  scramSessionId?: string;
  scramEncryptedCreds?: string;
};

type TestToolScramShaAuthProps = {
  scramCreds: ScramCreds;
  // eslint-disable-next-line
  onChange?: (creds: ScramCreds) => void;
};

const TestToolScramShaAuth: React.FC<TestToolScramShaAuthProps> = ({ scramCreds, onChange }) => {
  const [scramSessionId, setScramSessionId] = useState<string>('');
  const [scramEncryptedCreds, setScramEncryptedCreds] = useState<string>('');
  const { t } = useTranslation();

  useEffect(() => {
    setScramSessionId(scramCreds.scramSessionId ?? '');
    setScramEncryptedCreds(scramCreds.scramEncryptedCreds ?? '');
  }, [scramCreds.scramEncryptedCreds, scramCreds.scramSessionId]);

  const handleHttpScramSessionIdChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const scramSessionId = event.target.value;
    setScramSessionId(scramSessionId);
    if (onChange && typeof onChange === 'function') {
      onChange({ scramEncryptedCreds, scramSessionId });
    }
  };

  const handleHttpScramEncryptedCredsChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const scramEncryptedCreds = event.target.value;
    setScramEncryptedCreds(scramEncryptedCreds);
    if (onChange && typeof onChange === 'function') {
      onChange({ scramEncryptedCreds, scramSessionId });
    }
  };

  return (
    <div className="testToolScramShaAuth">
      <div className="scramsessionid">
        <div className="securityHeader">
          <div className="labelText">{t('session_identifier')}</div>
          <div className="requiredHighlight parameterIn">{t('required')}</div>
        </div>
        <TextInput id="scramsessionid" hideLabel labelText={t('session_identifier')} value={scramSessionId} onChange={handleHttpScramSessionIdChange} />
      </div>

      <div className="scramencryptedcreds">
        <div className="securityHeader">
          <div className="labelText">{t('encrypted_creds')}</div>
          <div className="requiredHighlight parameterIn">{t('required')}</div>
        </div>
        <TextInput
          id="scramencryptedcreds"
          labelText={t('encrypted_creds')}
          hideLabel
          value={scramEncryptedCreds}
          onChange={handleHttpScramEncryptedCredsChange}
        />
      </div>
    </div>
  );
};

export default TestToolScramShaAuth;
