import { useEffect, useState } from 'react';
import { CodeLanguagesTypes } from '../code-snippets/constants.ts';
import { useApi } from '../contexts/ApiHandler/index.tsx';

const useAsyncAPICodeSnippetLanguages = (schemaType: any, encodingType: any): string[] => {
  const { apiHandler } = useApi() as any;
  const [availableLanguages, updateAvailableLanguages] = useState<string[]>([]);

  useEffect(() => {
    // Iterate through the list of languages, removing any incompatible languages for a particular
    // schema type.
    updateAvailableLanguages(
      Object.values(CodeLanguagesTypes).filter((language) => {
        // kafka console consumer doesn't work with Avro schemas that are not JSON encoded.
        switch (language) {
          case CodeLanguagesTypes.kafkacat:
          case CodeLanguagesTypes.consoleConsumer:
            return !(apiHandler.isAvroSchema(schemaType) && encodingType !== 'application/json');
          default:
            return true;
        }
      })
    );
  }, [schemaType, apiHandler, encodingType]);

  return availableLanguages;
};

export default useAsyncAPICodeSnippetLanguages;

