import React, { useEffect, useState, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Button,
  Select,
  SelectItem,
  Loading
} from '@carbon/react';
import { findFirstAppWithAccess } from 'utils/common';
import { useApi } from '../contexts/ApiHandler/index.tsx';
import { useConfig } from '../contexts/config';
import TestToolResponse from './TestToolResponse.tsx';
import { TestToolODataParameters } from './TestToolODataParameters';
import Invoker from '../utils/invoker';

const DEFAULT_CLIENT_ID_HEADER = 'X-IBM-Client-Id';
const DEFAULT_CLIENT_SECRET_HEADER = 'X-IBM-Client-Secret';

function TestToolOData({ api, apps }) {
  const { t } = useTranslation();
  const { apiHandler } = useApi();
  const { options } = useConfig();
  const invoker = useMemo(() => new Invoker(), []);
  
  // State management
  const [endpoint, setEndpoint] = useState('');
  const [endpoints, setEndpoints] = useState([]);
  const [entitySets, setEntitySets] = useState([]);
  const [selectedEntitySet, setSelectedEntitySet] = useState('');
  const [navigationProperties, setNavigationProperties] = useState([]);
  const [selectedNavProperty, setSelectedNavProperty] = useState('');
  const [operations, setOperations] = useState([]);
  const [selectedOperation, setSelectedOperation] = useState('');
  const [loading, setLoading] = useState(false);
  const [response, setResponse] = useState(null);
  const [error, setError] = useState(null);
  
  // Parameters state for TestToolParameters component
  const [parameterState, setParameterState] = useState({
    parameterValues: {},
    accept: 'application/json',
    contentType: 'application/json'
  });
  
  // Security state
  const [security, setSecurity] = useState({
    identification: {
      clientID: null,
      clientSecret: '',
      externalApiKeys: {}
    },
    flags: {}
  });

  const initializeParameters = (entitySetName) => {
    if (!apiHandler.getODataQueryParameters) return;
    
    const parameters = apiHandler.getODataQueryParameters(entitySetName);
    const parameterValues = {};
    
    Object.keys(parameters).forEach((key) => {
      const param = parameters[key];
      parameterValues[key] = {
        ...param,
        value: '' // Initialize with empty string instead of undefined
      };
    });
    
    setParameterState({
      parameterValues,
      accept: 'application/json',
      contentType: 'application/json'
    });
  };

  // Clear response and reset ALL state when API changes
  useEffect(() => {
    setResponse(null);
    setError(null);
    setSelectedEntitySet('');
    setSelectedOperation('');
    setSelectedNavProperty('');
    setNavigationProperties([]);
    setParameterState({
      parameterValues: {},
      accept: 'application/json',
      contentType: 'application/json'
    });
  }, [api]);

  // Initialize endpoints, entity sets, and parameters
  useEffect(() => {
    if (api && apiHandler) {
      const apiEndpoints = apiHandler.getEndpoints(api, {});
      setEndpoints(apiEndpoints);
      
      if (apiEndpoints?.length > 0) {
        setEndpoint(apiEndpoints[0].url);
      }
      
      // Get entity sets (synchronous, triggers background fetch if needed)
      const sets = apiHandler.getEntitySets ? apiHandler.getEntitySets() : [];
      setEntitySets(sets);
      
      // Get operations (functions/actions)
      const ops = apiHandler.getOperations ? apiHandler.getOperations() : [];
      setOperations(ops);
      
      if (sets.length > 0) {
        setSelectedEntitySet(sets[0].name);
        initializeParameters(sets[0].name);
        
        // Get navigation properties for first entity set
        const navProps = apiHandler.getNavigationProperties ?
          apiHandler.getNavigationProperties(sets[0].name) : [];
        setNavigationProperties(navProps);
      }
      
      // Initialize security
      let credentials = null;
      if (apps && apps.length > 0 && apps[0].credentials && apps[0].credentials.length > 0) {
        const initialApp = findFirstAppWithAccess(apps);
        credentials = initialApp ? initialApp.credentials?.[0] : apps[0].credentials[0];
      }
      
      const operation = api.paths?.[`/${sets[0]?.name}`]?.get || {};
      const securityConfig = apiHandler.getSecurityConfig(api, operation, null, apiEndpoints[0]?.url);
      
      if (securityConfig) {
        setSecurity({
          identification: {
            clientID: credentials?.client_id || '',
            clientSecret: credentials?.client_secret || '',
            externalApiKeys: {}
          },
          flags: securityConfig.flags || {}
        });
      }
    }
  }, [api, apiHandler]);

  // Listen for OData metadata loaded event to refresh entity sets
  useEffect(() => {
    const handleMetadataLoaded = () => {
      if (api && apiHandler) {
        // Get entity sets
        const sets = apiHandler.getEntitySets ? apiHandler.getEntitySets() : [];
        setEntitySets(sets);
        
        // Get operations
        const ops = apiHandler.getOperations ? apiHandler.getOperations() : [];
        setOperations(ops);
        
        if (sets.length > 0 && !selectedEntitySet) {
          setSelectedEntitySet(sets[0].name);
          initializeParameters(sets[0].name);
          
          // Get navigation properties for first entity set
          const navProps = apiHandler.getNavigationProperties ?
            apiHandler.getNavigationProperties(sets[0].name) : [];
          setNavigationProperties(navProps);
        }
      }
    };

    window.addEventListener('odata-metadata-loaded', handleMetadataLoaded);
    return () => window.removeEventListener('odata-metadata-loaded', handleMetadataLoaded);
  }, [api, apiHandler, selectedEntitySet]);

  const handleEndpointChange = (event) => {
    setEndpoint(event.target.value);
  };

  const handleEntitySetChange = (event) => {
    const entitySetName = event.target.value;
    setSelectedEntitySet(entitySetName);
    setSelectedNavProperty(''); // Reset navigation property
    setSelectedOperation(''); // Reset operation
    initializeParameters(entitySetName);
    
    // Update navigation properties for selected entity set
    const navProps = apiHandler.getNavigationProperties ?
      apiHandler.getNavigationProperties(entitySetName) : [];
    setNavigationProperties(navProps);
  };

  const handleNavPropertyChange = (event) => {
    setSelectedNavProperty(event.target.value);
    setSelectedOperation(''); // Reset operation when nav property selected
  };

  // Filter operations based on selected entity set
  const availableOperations = useMemo(() => {
    if (!operations || operations.length === 0) return [];
    if (!selectedEntitySet) return operations.filter(op => !op.isBound);
    
    // Get the entity type for the selected entity set
    const entitySet = entitySets.find(es => es.name === selectedEntitySet);
    if (!entitySet) return operations.filter(op => !op.isBound);
    
    const { entityType } = entitySet;
    
    return operations.filter(op => {
      // Include unbound operations
      if (!op.isBound) return true;
      
      // Include bound operations that match the entity type
      if (op.bindingParameter) {
        // Check if binding parameter type matches entity type
        // Handle both Collection(Type) and Type formats
        const bindingType = op.bindingParameter.type;
        if (bindingType) {
          // Remove Collection() wrapper if present
          const cleanType = bindingType.replace(/^Collection\((.+)\)$/, '$1');
          // Match against full qualified name or just the type name
          return cleanType === entityType || cleanType.endsWith(`.${entityType.split('.').pop()}`);
        }
      }
      
      return false;
    });
  }, [operations, selectedEntitySet, entitySets]);

  const handleOperationChange = (event) => {
    const operationName = event.target.value;
    setSelectedOperation(operationName);
    setSelectedNavProperty(''); // Reset nav property when operation selected
    
    // Initialize parameters for the selected operation
    if (operationName) {
      const operation = operations.find(op => op.name === operationName);
      if (operation) {
        const parameterValues = {};
        
        // Add key parameter if operation is bound
        if (operation.isBound && selectedEntitySet) {
          const entitySet = entitySets.find(es => es.name === selectedEntitySet);
          if (entitySet && entitySet.keyProperties && entitySet.keyProperties.length > 0) {
            const keyProp = entitySet.keyProperties[0];
            parameterValues.key = {
              name: 'key',
              in: 'path',
              required: true,
              type: keyProp.type,
              description: `Key for ${selectedEntitySet}`,
              value: '',
              isOperationParam: false
            };
          }
        }
        
        // Add operation parameters
        if (operation.parameters && operation.parameters.length > 0) {
          operation.parameters.forEach(param => {
            parameterValues[param.name] = {
              name: param.name,
              in: 'query',
              required: !param.nullable,
              type: param.type,
              description: param.description || `Parameter ${param.name}`,
              value: '',
              isOperationParam: true
            };
          });
        }
        
        setParameterState({
          parameterValues,
          accept: 'application/json',
          contentType: 'application/json'
        });
      }
    } else if (selectedEntitySet) {
      // Reset to entity set parameters when operation is cleared
      initializeParameters(selectedEntitySet);
    }
  };

  const handleParameterChange = (updates) => {
    setParameterState(prev => ({
      ...prev,
      ...updates
    }));
  };

  // Helper function to check if OData type requires quotes
  const isStringType = (type) => {
    if (!type) return false;
    const stringTypes = ['Edm.String', 'string', 'Edm.Guid'];
    return stringTypes.includes(type);
  };

  const buildODataUrl = () => {
    if (!endpoint) return '';
    
    // Handle operation invocation
    if (selectedOperation) {
      const operation = operations.find(op => op.name === selectedOperation);
      if (operation) {
        // Build function/action URL
        if (operation.isBound && selectedEntitySet) {
          // Bound operation: /EntitySet(key)/Namespace.OperationName
          let url = `${endpoint}/${selectedEntitySet}`;
          const keyParam = parameterState.parameterValues.key;
          if (keyParam?.value && typeof keyParam.value === 'string' && keyParam.value.trim()) {
            const needsQuotes = isStringType(keyParam.type);
            url += needsQuotes ? `('${keyParam.value}')` : `(${keyParam.value})`;
          }
          url += `/${operation.name}`;
          
          // Add function parameters if any
          if (operation.type === 'function' && operation.parameters && operation.parameters.length > 0) {
            const params = operation.parameters
              .filter(p => parameterState.parameterValues[p.name]?.value)
              .map(p => {
                const paramValue = parameterState.parameterValues[p.name].value;
                const needsQuotes = isStringType(p.type);
                return `${p.name}=${needsQuotes ? `'${paramValue}'` : paramValue}`;
              })
              .join(',');
            if (params) url += `(${params})`;
          }
          return url;
        }
        // Unbound operation: /OperationName
        let url = `${endpoint}/${operation.name}`;
        if (operation.type === 'function' && operation.parameters && operation.parameters.length > 0) {
          const params = operation.parameters
            .filter(p => parameterState.parameterValues[p.name]?.value)
            .map(p => {
              const paramValue = parameterState.parameterValues[p.name].value;
              const needsQuotes = isStringType(p.type);
              return `${p.name}=${needsQuotes ? `'${paramValue}'` : paramValue}`;
            })
            .join(',');
          if (params) url += `(${params})`;
        }
        return url;
      }
    }
    
    // Handle entity set access
    if (!selectedEntitySet) return '';
    let url = `${endpoint}/${selectedEntitySet}`;
    
    // Add key parameter if provided (for single entity access)
    const keyParam = parameterState.parameterValues.key;
    if (keyParam?.value && typeof keyParam.value === 'string' && keyParam.value.trim()) {
      const needsQuotes = isStringType(keyParam.type);
      if (needsQuotes) {
        url = `${url}('${keyParam.value}')`;
      } else {
        url = `${url}(${keyParam.value})`;
      }
    }
    
    // Add navigation property if selected
    if (selectedNavProperty) {
      url = `${url}/${selectedNavProperty}`;
    }
    
    const queryParams = [];
    
    // Add OData system query options and custom query parameters
    Object.keys(parameterState.parameterValues).forEach((key) => {
      const param = parameterState.parameterValues[key];
      // Only add query parameters that have actual non-empty values
      // Skip undefined, null, empty strings, and whitespace-only values
      if (param.in === 'query' &&
          param.value &&
          typeof param.value === 'string' &&
          param.value.trim() !== '') {
        // Don't encode the parameter name (especially the $ prefix for OData system query options)
        // Only encode the parameter value
        queryParams.push(`${param.name}=${encodeURIComponent(param.value)}`);
      }
    });
    
    if (queryParams.length > 0) {
      url = `${url}?${queryParams.join('&')}`;
    }
    
    return url;
  };

  const buildHeaders = (url) => {
    // Use application/xml for $metadata, application/json for data
    const isMetadata = url && url.includes('$metadata');
    const headers = {
      'Content-Type': parameterState.contentType || 'application/json',
      'Accept': isMetadata ? 'application/xml' : (parameterState.accept || 'application/json')
    };
    
    // Add header parameters from parameterState
    Object.keys(parameterState.parameterValues).forEach((key) => {
      const param = parameterState.parameterValues[key];
      if (param.in === 'header' && param.value) {
        headers[param.name] = param.value;
      }
    });
    
    const config = security.flags;
    
    if (config.requiresClientId && config.clientIdLocation === 'header') {
      if (config.clientIdName) {
        headers[config.clientIdName] = security.identification.clientID;
      } else {
        headers[DEFAULT_CLIENT_ID_HEADER] = security.identification.clientID;
      }
    }
    
    if (config.requiresClientSecret && config.clientSecretLocation === 'header') {
      if (config.clientSecretName) {
        headers[config.clientSecretName] = security.identification.clientSecret;
      } else {
        headers[DEFAULT_CLIENT_SECRET_HEADER] = security.identification.clientSecret;
      }
    }
    
    return headers;
  };

  const handleSendRequest = async () => {
    setLoading(true);
    setError(null);
    setResponse(null);
    
    try {
      const url = buildODataUrl();
      const headers = buildHeaders(url);
      
      // Determine HTTP method
      let httpMethod = 'GET';
      if (selectedOperation) {
        const operation = operations.find(op => op.name === selectedOperation);
        // Actions use POST, Functions use GET
        httpMethod = operation?.type === 'action' ? 'POST' : 'GET';
      }
      
      // Use Invoker to handle CORS via proxy if configured
      const invokeConfig = {
        verb: httpMethod,
        operationPath: '',
        endpoint: url,
        targetUrl: url,
        headers,
        type: 'REST',
        version: '3.0',
        scheme: url.startsWith('https') ? 'https' : 'http',
        contentTypeHeader: headers['Content-Type'],
        acceptHeader: headers.Accept,
        parameterValues: {},
        proxyUrl: options?.proxyUrl || null
      };
      
      const invokeResponse = await invoker.invoke(invokeConfig, security.flags);
      
      // Map invoker response to the format expected by TestToolResponse
      setResponse(invokeResponse);
    } catch (err) {
      setError(err.message || err.toString());
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="odata-test-tool">
      <div className="odata-test-tool-config">
        {/* Endpoint Selector */}
        <div className="odata-config-section">
          <div className="odata-label">{t('endpoint')}</div>
          {endpoints && endpoints.length > 0 ? (
            <Select
              id="odata-endpoint-selector"
              onChange={handleEndpointChange}
              defaultValue={endpoints[0]?.url || ''}
              hideLabel
              size="sm"
              data-testid="odata-endpoint-selector"
            >
              {endpoints.map((ep, index) => {
                const endpointTypesText = ep.types ? `${ep.types}: ` : '';
                const displayText = `${endpointTypesText}${ep.url}`;
                return (
                  <SelectItem
                    key={ep.url || `endpoint-${index}`}
                    value={ep.url || ''}
                    text={displayText || `Endpoint ${index + 1}`}
                  />
                );
              })}
            </Select>
          ) : (
            <div>{t('no_endpoints_available')}</div>
          )}
        </div>

        {/* Entity Set Selector */}
        <div className="odata-config-section">
          <div className="odata-label">{t('entity_set')}</div>
          {entitySets && entitySets.length > 0 ? (
            <Select
              id="odata-entityset-selector"
              onChange={handleEntitySetChange}
              defaultValue={entitySets[0]?.name || ''}
              hideLabel
              size="sm"
              data-testid="odata-entityset-selector"
            >
              {entitySets.map((entitySet, index) => (
                <SelectItem
                  key={entitySet.name || `entityset-${index}`}
                  value={entitySet.name || ''}
                  text={entitySet.name || `Entity Set ${index + 1}`}
                />
              ))}
            </Select>
          ) : (
            <div>{t('no_entity_sets_available')}</div>
          )}
        </div>

        {/* Navigation Property Selector */}
        {navigationProperties && navigationProperties.length > 0 && !selectedOperation && (
          <div className="odata-config-section">
            <div className="odata-label">{t('navigation_property')}</div>
            <Select
              id="odata-navproperty-selector"
              onChange={handleNavPropertyChange}
              value={selectedNavProperty}
              hideLabel
              size="sm"
            >
              <SelectItem value="" text={t('none')} />
              {navigationProperties.map((navProp, index) => (
                <SelectItem
                  key={navProp.name || `navprop-${index}`}
                  value={navProp.name || ''}
                  text={`${navProp.name} (${navProp.type})`}
                />
              ))}
            </Select>
          </div>
        )}

        {/* Operation Selector (Functions/Actions) */}
        {operations && operations.length > 0 && !selectedNavProperty && (
          <div className="odata-config-section">
            <div className="odata-label">{t('operation')}</div>
            <Select
              id="odata-operation-selector"
              onChange={handleOperationChange}
              value={selectedOperation}
              hideLabel
              size="sm"
            >
              <SelectItem value="" text={t('none')} />
              {availableOperations.map((op, index) => (
                <SelectItem
                  key={op.name || `operation-${index}`}
                  value={op.name || ''}
                  text={`${op.name} (${op.type}${op.isBound ? ', bound' : ''})`}
                />
              ))}
            </Select>
          </div>
        )}
  
        {/* Parameters Section */}
        {Object.keys(parameterState.parameterValues).length > 0 && (
          <TestToolODataParameters
            key={selectedEntitySet}
            parameters={parameterState.parameterValues}
            onChange={handleParameterChange}
          />
        )}

        {/* Request URL Preview */}
        <div className="odata-url-preview">
          <div className="odata-label">{t('request_url')}</div>
          <div className="odata-url-text">{buildODataUrl()}</div>
        </div>

        {/* Send Button */}
        <Button
          onClick={handleSendRequest}
          disabled={
            loading ||
            !endpoint ||
            !selectedEntitySet ||
            (selectedNavProperty && (!parameterState.parameterValues.key?.value || !parameterState.parameterValues.key.value.trim())) ||
            // Disable if operation has required parameters that are not filled
            (!!selectedOperation && Object.values(parameterState.parameterValues).some(param =>
              param.isOperationParam && param.required && (!param.value || String(param.value).trim() === '')
            ))
          }
          size="sm"
        >
          {loading ? t('sending') : t('send_request')}
        </Button>
        
        {/* Validation message */}
        {selectedNavProperty && (!parameterState.parameterValues.key?.value || !parameterState.parameterValues.key.value.trim()) && (
          <div className="odata-validation-message" style={{ color: '#da1e28', marginTop: '8px', fontSize: '12px' }}>
            {t('navigation_requires_key') || 'Navigation properties require a key value for the entity'}
          </div>
        )}
      </div>

      {/* Response Display */}
      {loading && <Loading description={t('loading')} withOverlay={false} />}
      
      {error && (
        <div className="odata-error">
          <h4>{t('error')}</h4>
          <pre>{error}</pre>
        </div>
      )}
      
      {response && (
        <TestToolResponse
          invokeResponse={response}
          responseBody={response.responseDataString}
          contentFormat="json"
        />
      )}
    </div>
  );
}

export default TestToolOData;

