import { useEffect } from 'react';

const LS_KEY = 'apiConnectExplorer.theme';
const THEME_CLASSES = ['theme-white', 'theme-g10', 'theme-g90', 'theme-g100'];

function getRootNode() {
  try {
    const attach = window.apiConnectExplorer && window.apiConnectExplorer.attachPoint;
    if (attach) {
      if (typeof attach === 'string') {
        // try querySelector first (supports CSS selector or tag), then id fallback
        const el = document.querySelector(attach) || document.getElementById(attach.replace(/^#/, ''));
        if (el) return el;
      } else if (attach instanceof HTMLElement) {
        return attach;
      }
    }
  } catch (e) {
    console.error('Error getting attachPoint for ThemeSync:', e);
  }

  // existing fallbacks
  return document.querySelector('apiconnect-explorer') || document.getElementById('apiconnect-explorer') || document.querySelector('.apiconnect-explorer-root');
}

function applyClassToRoot(theme) {
  try {
    const root = getRootNode();
    if (!root) return;
    // remove previous theme classes
    THEME_CLASSES.forEach(c => root.classList.remove(c));
    // map theme to class
    if (!theme || theme === 'white' || theme === 'g10') {
      root.classList.add('theme-white');
    } else if (theme === 'g90' || theme === 'g100') {
      root.classList.add('theme-g90');
    }
  } catch (err) {
    console.error('Error applying theme class to root:', err);
  }
}

function setGlobalExplorerTheme(theme) {
  try {
    window.apiConnectExplorer = window.apiConnectExplorer || {};
    window.apiConnectExplorer.options = window.apiConnectExplorer.options || {};
    window.apiConnectExplorer.options.theme = theme;
  } catch {
    // ignore
  }
}

export default function ThemeSync() {
  useEffect(() => {
    try {
      const saved = localStorage.getItem(LS_KEY);
      if (saved) {
        setGlobalExplorerTheme(saved);
        applyClassToRoot(saved);
      }
    } catch {
      // ignore localStorage read errors
    }

    function onStorage(e) {
      if (e.key === LS_KEY) {
        const t = e.newValue;
        setGlobalExplorerTheme(t);
        applyClassToRoot(t);
      }
    }

    function onCustomEvent(ev) {
      // Prefer theme from event detail, otherwise check global
      const t = ev?.detail?.theme || window.apiConnectExplorer?.options?.theme;
      if (t) {
        // portal already writes to localStorage; don't re-write here to avoid loops
        setGlobalExplorerTheme(t);
        applyClassToRoot(t);
      }
    }

    window.addEventListener('storage', onStorage);
    window.addEventListener('apiConnectExplorerUpdate', onCustomEvent);

    return () => {
      window.removeEventListener('storage', onStorage);
      window.removeEventListener('apiConnectExplorerUpdate', onCustomEvent);
    };
  }, []);

  return null;
}
