import React, { useState, useEffect } from 'react';
import classNames from 'classnames';
import { useTranslation } from 'react-i18next';
import { CaretRight } from '@carbon/react/icons';
import { Link } from 'react-router-dom';
import DOMPurify from 'dompurify';
import withActionHandler from '../utils/withActionHandler';
import { cleanUpKey, highlightCleaner } from '../utils/common';

type MenuItem = {
  displayName: string, // page display name
  selected: boolean, // if the item is in a selected state
  route: string, // route to navigate to on click
}

type NestedMenus = Record<string, MenuDropdownProps>;

type MenuDropdownProps = {
  displayName: string, // display name of the dropdown
  menuItems: MenuItem[],
  nestedMenus: NestedMenus, // keys are display names for nested dropdown, values are menuDropdown props
  className: string,
  to?: boolean,
  onToggle: (e: boolean) => void, // function that triggers on dropdown toggle
  isExpanded: boolean, // expanded prop used to drive external expand/collapse for functionality like expand all/collapse all.
  highlightedQuery?: string, // Optional HTML to show highlighted query
  selected?: any,
}

const MenuDropdown = ({ displayName, selected, menuItems, onToggle = () => {}, to, nestedMenus = {}, isExpanded, highlightedQuery }: MenuDropdownProps) => {
  const { t } = useTranslation();

  const [expanded, updateExpanded] = useState<boolean>(false);

  // if isExpanded prop change, use that to drive state
  useEffect(() => {
    if (isExpanded !== null) {
      updateExpanded(isExpanded);
    }
  }, [isExpanded]);

  const toggleDisplay = withActionHandler(() => {
    updateExpanded(!expanded);
    onToggle(!expanded);
  });

  let highlight;
  if (highlightedQuery) {
    highlight = highlightCleaner(displayName, highlightedQuery);
  }

  const renderLink = (jsx: React.ReactNode) => {
    // only render react router link if clicking the dropdown takes the user somewhere
    if (to) {
      return (
        <Link
          className={classNames('menuDropdown tocHeader', { selected })}
          to={to}
          title={displayName}
          aria-label={displayName}
          data-testid="menuDropdown-navigate"
        >
          {jsx}
        </Link>
      );
    }
    return (
      <div className={classNames('menuDropdown tocHeader', { selected })} aria-label={displayName}>
        {jsx}
      </div>
    );
  };

  return (
    <div data-testid="menu-dropdown">
      <div className="clickable">
        {renderLink(
          <>
            {/* eslint-disable-next-line react/button-has-type */}
            <button className={classNames('iconOnlyButton')} onClick={toggleDisplay} aria-label={t('menu_button')} data-testid="menuDropdown-button">
              <CaretRight size={32} className={classNames('expand-arrow', { rotate90: expanded })} />
            </button>
            <div className="menuDropdown__label truncate">
              <p className="truncate">{highlight ? <span dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(highlight) }} /> : displayName}</p>
            </div>
          </>
        )}
      </div>
      {expanded && (
        <ul>
          {nestedMenus &&
            Object.entries(nestedMenus).map(([key, value]: [string, MenuDropdownProps]) => (
              <li key={key} className="tocItem tocHeader" data-testid="grouped-menu-item">
                <MenuDropdown
                  className="nestedTag"
                  menuItems={value.menuItems}
                  displayName={key}
                  nestedMenus={value.nestedMenus}
                  onToggle={value.onToggle}
                  isExpanded={isExpanded}
                />
              </li>
            ))}
          {menuItems.map((menuItem) => {
            const itemKey = cleanUpKey(menuItem.displayName);

            return (
              <li className="tocItem" key={`${displayName}/${itemKey}`}>
                <Link
                  to={menuItem.route}
                  className={classNames('cds--side-nav__link', 'truncate toc-selectable menuDropdown__item', `toc-navigate-${cleanUpKey(itemKey)}`, {
                    selected: menuItem.selected
                  })}
                  title={menuItem.displayName}
                  data-testid="dropdown-item-list"
                >
                  <span className="cds--side-nav__link-text" dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(menuItem.displayName) }} data-testid="grouped-menu-item" />
                </Link>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

export default MenuDropdown;
