/* eslint-disable react/jsx-props-no-spreading */

import React, { Suspense, lazy } from 'react';
import { SkeletonText } from '@carbon/react';

const CodeViewerImpl = lazy(() => import('./CodeViewerImpl.tsx'));

type CodeViewerProps = {
  codeLanguage?: string;
  className?: string;
  children?: React.ReactNode;
  highlight?: boolean;
};

const CodeViewer = (props: CodeViewerProps): React.ReactElement => (
  <Suspense fallback={<SkeletonText paragraph />}>
    <CodeViewerImpl {...props} />
  </Suspense>
);

export default CodeViewer;
