import { useState, useEffect, useMemo, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
// @ts-ignore
import { useApi } from 'contexts/ApiHandler';
// @ts-ignore
import JavaKafkaCodeSnippet from 'code-snippets/KafkaSnippets/JavaKafkaCodeSnippet';

type PropertyKeys = {
  keyDeserializer: string;
  valueDeserializer: string;
  bootstrapServers: string;
  clientId: string;
  saslMechanism: string;
  securityProtocol: string;
}

type KafkaProperty = {
  key: string;
  value: string;
}

const propertyKeys: PropertyKeys = {
  keyDeserializer: 'key.deserializer',
  valueDeserializer: 'value.deserializer',
  bootstrapServers: 'bootstrap.servers',
  clientId: 'client.id',
  saslMechanism: 'sasl.mechanism',
  securityProtocol: 'security.protocol'
};

const useKafkaProperties = (channelName: string, operationId?: string): KafkaProperty[] => {
  const [properties, updateProperties] = useState<KafkaProperty[]>([]);
  const { t } = useTranslation();
  const { apiHandler } = useApi();
  
  // Java code snippet properties are the same as kafka properties so re-use that here
  const parser = useMemo(
    () => new JavaKafkaCodeSnippet(apiHandler, channelName, {}, t, undefined, operationId), 
    [apiHandler, channelName, operationId, t]
  );
  
  const getPropertyForKey = useCallback(
    (key: string): KafkaProperty | undefined => {
      switch (key) {
        case propertyKeys.keyDeserializer:
          return {
            key,
            value: parser.getKeyDeserializer().deserializerClass
          };
        case propertyKeys.valueDeserializer:
          return {
            key,
            value: parser.getSchemaInformation().deserializerClass
          };
        case propertyKeys.bootstrapServers:
          return {
            key,
            value: parser.getBootstrapServers()
          };
        case propertyKeys.clientId:
          return {
            key,
            value: parser.getOperationBindings().clientId
          };
        case propertyKeys.saslMechanism:
          return {
            key,
            value: parser.getSecurityDetails().saslMechanism
          };
        case propertyKeys.securityProtocol:
          return {
            key,
            value: parser.getSecurityDetails().securityProtocol
          };
        default:
          return undefined;
      }
    },
    [parser]
  );

  useEffect(() => {
    const propertiesList = Object.values(propertyKeys)
      .map((propertyKey) => getPropertyForKey(propertyKey))
      .filter((property): property is KafkaProperty => !!property && !!property.value); // remove any properties that we couldn't work out the value for
    updateProperties(propertiesList);
  }, [channelName, getPropertyForKey]);

  return properties;
};

export default useKafkaProperties;
