import { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { isEmpty } from 'lodash';
import { useConfig } from '../contexts/config';
import { useApi } from '../contexts/ApiHandler/index.tsx';
import snippetFactory from './snippetFactory.ts';
import { ApiTypes, CodeLanguagesTypes } from './constants.ts';
import { SnippetResult } from './kafka.ts';

import JavaKafkaCodeSnippet from './KafkaSnippets/JavaKafkaCodeSnippet.ts';
import KafkaJSKafkaCodeSnippet from './KafkaSnippets/KafkaJSKafkaCodeSnippet.ts';
import NoderdKafkaCodeSnippet from './KafkaSnippets/PythonKafkaCodeSnippet.ts';
import PythonKafkaCodeSnippet from './KafkaSnippets/NoderdKafkaCodeSnippet.ts';
import KafkacatKafkaCodeSnippet from './KafkaSnippets/KafkacatKafkaCodeSnippet.ts';
import KafkaConsoleConsumerCodeSnippet from './KafkaSnippets/KafkaConsoleConsumerCodeSnippet.ts';

export type SelectedCredentials = {
  application?: string,
  credential: string
}

type UseGenerateSnippetProps = {
  apiType: ApiTypes,
  codeLanguage: CodeLanguagesTypes,
  channelName: string,
  selectedCredentials: SelectedCredentials,
  operationId: string
}

const useGenerateKafkaSnippet = ({ apiType, codeLanguage, channelName, selectedCredentials, operationId }: UseGenerateSnippetProps) => {
  const { apiHandler }: any = useApi();
  const { t } = useTranslation();
  const { options }: any = useConfig();

  const [generatedSnippetOptions, updateGeneratedSnippetOptions] = useState({});
  const [generatedSnippet, updateGeneratedSnippet] = useState<SnippetResult>({ snippet: '', dependencies: '' });
  const getClassForLanguage = useCallback(
    (codeLanguage: CodeLanguagesTypes) => {
      switch (codeLanguage) {
        case CodeLanguagesTypes.java:
          return new JavaKafkaCodeSnippet(apiHandler, channelName, selectedCredentials, t, options.loggedIn, operationId);
        case CodeLanguagesTypes.consoleConsumer:
          return new KafkaConsoleConsumerCodeSnippet(apiHandler, channelName, selectedCredentials, t, options.loggedIn, operationId);
        case CodeLanguagesTypes.kafkaJS:
          return new KafkaJSKafkaCodeSnippet(apiHandler, channelName, selectedCredentials, t, options.loggedIn, operationId);
        case CodeLanguagesTypes.noderdKafka:
          return new NoderdKafkaCodeSnippet(apiHandler, channelName, selectedCredentials, t, options.loggedIn, operationId);
        case CodeLanguagesTypes.kafkaPython:
          return new PythonKafkaCodeSnippet(apiHandler, channelName, selectedCredentials, t, options.loggedIn, operationId);
        case CodeLanguagesTypes.kafkacat:
          return new KafkacatKafkaCodeSnippet(apiHandler, channelName, selectedCredentials, t, options.loggedIn, operationId);
        default: {
          throw new Error(`Snippet options for ${codeLanguage} is not supported`);
        }
      }
    },
    [apiHandler, channelName, selectedCredentials, t, options.loggedIn, operationId]
  );

  useEffect(() => {
    const snippetLanguage = getClassForLanguage(codeLanguage);
    updateGeneratedSnippetOptions({
      channel: channelName,
      operationBindings: snippetLanguage.getOperationBindings(),
      securityDetails: snippetLanguage.getSecurityDetails(),
      bootstrapServers: snippetLanguage.getBootstrapServers(),
      schema: snippetLanguage.getSchemaInformation(),
      kafkaKey: snippetLanguage.getKeyDeserializer(),
      applicationDetails: snippetLanguage.getApplicationDetails(),
      encodingType: snippetLanguage.getEncodingType(),
      enforced: snippetLanguage.getEnforcedType()
    });
  }, [apiHandler, channelName, selectedCredentials, codeLanguage, getClassForLanguage, operationId]);

  useEffect(() => {
    if (!isEmpty(generatedSnippetOptions)) {
      const result = snippetFactory(apiType)(codeLanguage, generatedSnippetOptions);
      updateGeneratedSnippet({
        snippet: result.snippet,
        dependencies: result.dependencies || ''
      });
    }
  }, [generatedSnippetOptions, apiType, codeLanguage]);

  return {
    snippet: generatedSnippet.snippet,
    dependencies: generatedSnippet.dependencies
  };
};

export default useGenerateKafkaSnippet;
